using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() returned metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type that IS resolvable (default reflection resolver handles it)
if (options.TryGetTypeInfo<Person>(out var resolvedInfo))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded – type: {resolvedInfo!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false (unexpected)");

// 2b. Type that is NOT resolvable (empty resolver → no metadata)
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            // Strip every type except string
            ti => { if (ti.Type != typeof(string)) ti.Properties.Clear(); }
        }
    }
};

// Use a custom resolver that resolves nothing, to guarantee failure
var empty = new JsonSerializerOptions { TypeInfoResolver = JsonTypeInfoResolver.Combine() };

if (empty.TryGetTypeInfo<Person>(out var notFound))
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded (unexpected): {notFound!.Type.Name}");
else
    Console.WriteLine("TryGetTypeInfo<Person> returned false – no exception thrown ✓");

public record Person(string Name, int Age);

